// Generated by scripts/build-first-paint-kit.mjs from tools/first-paint/render.mjs: do not edit; edit the source and run it again.
// The first paint of a Smart component from its settings: settings JSON in,
// the host as a server prints it out (its attributes, its JSON island, the
// static markup marked data-sf-static) with the sheets that markup needs.
// It draws the component exactly as scripts/snapshot-first-paint.mjs draws an
// example (first-paint-lib.mjs drawExample: same page, real Loader, same
// settling, same serializer), so a request with an example's settings
// answers that example's committed snapshot, byte for byte. Nothing is
// guessed: an unknown tag, an undeclared setting or value, a template the
// component does not declare and a setting that arrives after the first
// paint are refused, never printed wrong.
//
// Usage: node tools/first-paint/render.mjs --distr=<root> [options] < request.json
//        node tools/first-paint/render.mjs --distr=<root> --session [options]   (JSON lines)
//
// The pair ships it as distr/core/js/composition/first-paint-render.mjs
// (scripts/build-first-paint-kit.mjs). Documented in
// docs/developer/first-paint-render.md; request and answer:
// contracts/schema/first-paint-render.schema.json.
import {createHash} from 'node:crypto';
import {existsSync, mkdirSync, readFileSync, readdirSync, renameSync, statSync, writeFileSync} from 'node:fs';
import {createInterface} from 'node:readline';
import {join, relative, resolve, sep} from 'node:path';
import {pathToFileURL} from 'node:url';
import {PAGE_SCRIPT, PROPERTY_ONLY, describe, drawExample, isDistribution, isInstant, launchChromium, memberOf, outputMounts, readConfig, serveOutput, snapshotIndex, sortedAttributes} from './engine.mjs';

// The format's name carries no version (journal record
// format-names-without-version): its major is schema_version.
export const SCHEMA = 'simai.first-paint-render';
export const SCHEMA_VERSION = 1;
const THEMES = ['theme-light', 'theme-dark'];
const REQUEST_FIELDS = new Set(['schema', 'schema_version', 'id', 'tag', 'template', 'settings', 'attributes', 'children', 'slots', 'markup', 'lang', 'now', 'prefix', 'url']);
// The page's address when the request gives none: a fixed one, so what a
// component resolves against the page (a copy link's full URL) is the same
// on every run and every machine. Never fetched: the renderer answers it.
export const PAGE_URL = 'https://first-paint.invalid/page';
// Attributes a page writes on a host that are not settings: its name for
// people, its id, its own data-*. A setting goes in `settings`.
const PAGE_ATTRIBUTE = /^(?:aria-[a-z-]+|role|id|title|lang|dir|class|data-(?!sf-)[a-z0-9-]+)$/u;

/** One JSON text for a value: keys in code-unit order at every depth. */
export function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().filter((key) => value[key] !== undefined).map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

const sha256 = (text) => createHash('sha256').update(text).digest('hex');

/**
 * The build's identity when the caller names none: the sha256 of every file
 * it serves (gzip copies left out: their bytes differ by platform), path and
 * content. Same files, same identity, on any machine.
 */
export function buildIdentity(roots) {
  const lines = [];
  for (const [prefix, root] of roots) {
    const walk = (folder) => {
      for (const one of readdirSync(folder, {withFileTypes: true}).sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))) {
        const path = join(folder, one.name);
        if (one.isDirectory()) walk(path);
        else if (one.isFile() && !one.name.endsWith('.gz')) lines.push(`${prefix}${relative(root, path).split(sep).join('/')}\0${sha256(readFileSync(path))}`);
      }
    };
    if (existsSync(root)) walk(root);
  }
  return `sha256:${sha256(lines.join('\n'))}`;
}

/** The Smart components a build serves, by tag: their folder and the root holding it. */
function componentIndex(distr, packages) {
  const roots = [isDistribution(distr) ? join(distr, 'smart') : join(distr, 'smart', 'smart'), ...Object.values(packages).map((one) => one.output)];
  const byTag = new Map();
  for (const root of roots) {
    if (!existsSync(root)) continue;
    for (const folder of readdirSync(root).sort()) {
      const file = join(root, folder, 'component.json');
      if (!existsSync(file)) continue;
      let manifest;
      try { manifest = JSON.parse(readFileSync(file, 'utf8')); } catch { continue; }
      if (!manifest.tag || manifest.kind === 'assembly' || byTag.has(manifest.tag)) continue;
      byTag.set(manifest.tag, {root, folder});
    }
  }
  return byTag;
}

const refuse = (reason, detail) => ({status: 'refused', reason, detail});

/**
 * Checks a request against the component's manifest, without a browser.
 * Answers {component, example, template, prefix, lang} or a refusal.
 */
function admit(request, index, languages) {
  if (!request || typeof request !== 'object' || Array.isArray(request)) return refuse('not-a-request', 'a request is a JSON object');
  const extra = Object.keys(request).filter((key) => !REQUEST_FIELDS.has(key));
  if (extra.length) return refuse('unknown-field', `not a request field: ${extra.join(', ')}`);
  if (request.schema !== undefined && request.schema !== SCHEMA) return refuse('schema', `this renderer answers ${SCHEMA}`);
  if (request.schema_version !== undefined && request.schema_version !== SCHEMA_VERSION) return refuse('schema', `this renderer answers ${SCHEMA} schema_version ${SCHEMA_VERSION}`);
  if (typeof request.tag !== 'string' || !/^sf-[a-z0-9-]+$/u.test(request.tag)) return refuse('tag', 'tag is an sf-* element name');
  const found = index.get(request.tag);
  if (!found) return {status: 'unknown', reason: 'unknown-tag', detail: `this build defines no <${request.tag}>`};
  const component = describe(found.root, found.folder);
  const templates = Object.keys(component.manifest.templates ?? {default: {}});
  const settings = request.settings ?? {};
  if (!settings || typeof settings !== 'object' || Array.isArray(settings)) return refuse('settings', 'settings is an object of setting names');
  // A template may come in settings, as the documented examples give it
  // (sf-avatar's "label" and "card"); it stays there, so the host is written
  // as the runtime writes it.
  const named = Object.hasOwn(settings, 'template') && !memberOf(component.manifest, 'template') ? settings.template : undefined;
  if (named !== undefined && request.template !== undefined && request.template !== named) return refuse('template', 'template is given twice with two values');
  const template = request.template ?? named ?? 'default';
  if (typeof template !== 'string' || !templates.includes(template)) return refuse('template', `<${request.tag}> declares the templates ${templates.join(', ')}`);
  for (const [name, value] of Object.entries(settings)) {
    if (name === 'template' && named !== undefined) continue;
    const member = memberOf(component.manifest, name);
    if (!member) return refuse('unknown-setting', `<${request.tag}> declares no setting or value ${name}`);
    if (component.late.includes(name) && value !== null && value !== undefined && !(Array.isArray(value) && !value.length)) {
      return refuse('late-setting', `${name} arrives after the first paint (§5.4): leave it out and give it to the element on the page`);
    }
    if (member.type === 'enum' && Array.isArray(member.values) && value !== null && !member.values.includes(String(value))) {
      return refuse('value', `${name} is one of ${member.values.map((one) => JSON.stringify(one)).join(', ')}`);
    }
    if (member.type === 'boolean' && typeof value !== 'boolean' && value !== null) return refuse('value', `${name} is true or false`);
    if (PROPERTY_ONLY.has(member.type) && value !== null && typeof value !== 'object') return refuse('value', `${name} is a list or an object (a JSON island)`);
  }
  const attributes = request.attributes ?? {};
  if (!attributes || typeof attributes !== 'object' || Array.isArray(attributes)) return refuse('attributes', 'attributes is an object of attribute names');
  for (const [name, value] of Object.entries(attributes)) {
    if (memberOf(component.manifest, name)) return refuse('attributes', `${name} is a setting: give it in settings`);
    if (name === 'template') return refuse('attributes', 'the template is the request\'s template');
    if (!PAGE_ATTRIBUTE.test(name)) return refuse('attributes', `${name} is not an attribute a page writes on a host (aria-*, role, id, title, lang, dir, class, data-*)`);
    if (!['string', 'boolean'].includes(typeof value) && value !== null) return refuse('attributes', `${name} is a string, true or false`);
  }
  for (const field of ['children', 'markup']) {
    if (request[field] !== undefined && typeof request[field] !== 'string' && !(field === 'children' && Array.isArray(request[field]) && request[field].every((one) => typeof one === 'string'))) {
      return refuse(field, `${field} is markup (a string)`);
    }
  }
  if (request.slots !== undefined && (!request.slots || typeof request.slots !== 'object' || Array.isArray(request.slots) || Object.values(request.slots).some((one) => typeof one !== 'string'))) {
    return refuse('slots', 'slots maps a slot name to its markup');
  }
  const lang = request.lang ?? 'ru';
  if (typeof lang !== 'string' || !languages.has(lang)) return refuse('lang', `this build has the language files ${[...languages].sort().join(', ')}`);
  if (request.now !== undefined && !isInstant(request.now)) return refuse('now', 'now is an ISO date-time with its offset');
  if (request.url !== undefined && (typeof request.url !== 'string' || !/^https?:\/\/[^/?#\s]+\/[^#\s]*$/u.test(request.url))) return refuse('url', 'url is the page\'s absolute http(s) address with a path');
  const prefix = request.prefix ?? `sf-${found.folder}`;
  if (typeof prefix !== 'string' || !/^[a-z][a-z0-9-]*$/iu.test(prefix)) return refuse('prefix', 'prefix is a name: letters, digits and hyphens');
  const example = {
    name: String(request.id ?? 'render'),
    settings,
    attributes: template === 'default' || named !== undefined ? attributes : {...attributes, template},
    ...(request.children !== undefined ? {children: request.children} : {}),
    ...(request.slots !== undefined ? {slots: request.slots} : {}),
    ...(request.markup !== undefined ? {markup: request.markup} : {}),
    ...(request.now !== undefined ? {'first-paint': {now: request.now}} : {}),
  };
  return {component, example, template, prefix, lang, url: request.url ?? PAGE_URL};
}

/** The component's committed first-paint sheets (static/sheets.json), or none. */
function committedSheets(component) {
  try {
    const kept = JSON.parse(readFileSync(join(component.dir, 'static', 'sheets.json'), 'utf8'));
    return Array.isArray(kept.sheets) ? kept.sheets.filter((one) => typeof one === 'string') : [];
  } catch {
    return [];
  }
}

/**
 * A renderer over one Framework build: one server and one browser for every
 * request. Close it when done.
 *
 *   distr        a pair's distr/ or a ui-builder build output (required)
 *   config       a first-paint configuration file (component packages, clock)
 *   build        the build's identity in the cache key (a pair id); default:
 *                the sha256 of the files it serves (buildIdentity)
 *   cache        a folder of answers by key: a request answered before is
 *                read from it and starts no browser
 *   concurrency  components drawn at once (default 2)
 *   timeout      ms a component may take to draw (default 20000)
 *   browser      a Playwright browser to use (not closed by the renderer)
 *   playwright   the playwright package folder (the pair's engine only)
 */
export async function createRenderer({distr, config = null, build = null, cache = null, concurrency = 2, port = 0, timeout = 20000, browser: given = null, playwright = null} = {}) {
  if (!distr) throw new Error('distr is required: the distribution root (core/, rule/, component/, utility/, smart/)');
  const root = resolve(distr);
  const run = config ? readConfig([`--config=${config}`], {}) : readConfig([], {});
  const index = componentIndex(root, run.packages);
  const langDir = isDistribution(root) ? join(root, 'core', 'lang') : join(root, 'core', 'core', 'lang');
  const languages = new Set(existsSync(langDir) ? readdirSync(langDir).filter((one) => /^[a-z]{2,3}(?:-[a-z0-9]+)*\.js$/u.test(one)).map((one) => one.slice(0, -3)) : []);
  const served = [...outputMounts(root), ...Object.values(run.packages).map(({base, output}) => [base, output])];
  const identity = build ?? buildIdentity(served);
  // The committed snapshots by their markup, and by it with its attributes
  // in name order (a snapshot printed in another order is the same markup).
  const snapshots = snapshotIndex(root);
  const sorted = new Map([...snapshots].map(([body, path]) => [sortedAttributes(body), path]));
  const pages = new Map([['/first-paint-page.js', PAGE_SCRIPT]]);
  let site = null;
  let browser = given;
  let serial = 0;
  const stats = {requests: 0, drawn: 0, cached: 0, refused: 0, unknown: 0, failed: 0};

  async function start() {
    if (!site) site = await serveOutput(root, {pages, packages: run.packages, port});
    if (!browser) browser = await launchChromium({playwright});
  }

  const keyOf = (request, admitted) => `sha256:${sha256(canonicalJson({
    schema: SCHEMA,
    schema_version: SCHEMA_VERSION,
    build: identity,
    tag: request.tag,
    template: admitted.template,
    settings: request.settings ?? {},
    attributes: request.attributes ?? {},
    children: request.children,
    slots: request.slots,
    markup: request.markup,
    lang: admitted.lang,
    now: request.now,
    prefix: admitted.prefix,
    url: admitted.url,
  }))}`;

  async function draw(admitted) {
    serial += 1;
    try {
      const got = await drawExample({browser, site, pages, path: `/render/${serial}`, address: admitted.url, title: admitted.component.tag, component: admitted.component, example: admitted.example, prefix: admitted.prefix, lang: admitted.lang, timeout, run});
      if (got.errors.length) return {status: 'failed', reason: 'page-error', detail: got.errors.join('; ').slice(0, 400)};
      // What this page asked for, with every sheet the component's committed
      // first paint names: a sheet the Loader asks for on one run and not on
      // another (a utility already in flight) is in every answer.
      const drawn = got.sheets.map((path) => path.replace(/^\/distr\//u, ''));
      return {status: 'printed', html: got.html, sheets: [...new Set([...drawn, ...committedSheets(admitted.component)])].sort()};
    } catch (error) {
      return {status: 'failed', reason: 'not-drawn', detail: String(error?.message ?? error).split('\n')[0].slice(0, 400)};
    }
  }

  /** The answer to one request (simai.first-paint-render, schema_version 1). */
  async function render(request) {
    stats.requests += 1;
    const id = request && typeof request === 'object' && !Array.isArray(request) ? request.id ?? null : null;
    const admitted = admit(request, index, languages);
    if (admitted.status) {
      stats[admitted.status === 'unknown' ? 'unknown' : 'refused'] += 1;
      return {schema: SCHEMA, schema_version: SCHEMA_VERSION, id, build: identity, status: admitted.status, tag: typeof request?.tag === 'string' ? request.tag : null, reason: admitted.reason, detail: admitted.detail};
    }
    const key = keyOf(request, admitted);
    const file = cache ? join(resolve(cache), `${key.slice('sha256:'.length)}.json`) : null;
    if (file && existsSync(file)) {
      try {
        const kept = JSON.parse(readFileSync(file, 'utf8'));
        if (kept.key === key) {
          stats.cached += 1;
          return {...kept, id};
        }
      } catch {
        // drawn again below
      }
    }
    await start();
    const got = await draw(admitted);
    const notes = [];
    if (admitted.component.overlay && 'open' in (request.settings ?? {})) notes.push('overlay-closed');
    const answer = got.status === 'printed'
      ? {schema: SCHEMA, schema_version: SCHEMA_VERSION, id, key, build: identity, status: 'printed', tag: request.tag, template: admitted.template, html: got.html, sheets: got.sheets, theme: THEMES,
        snapshot: snapshots.get(got.html) ?? sorted.get(sortedAttributes(got.html)) ?? null, notes}
      : {schema: SCHEMA, schema_version: SCHEMA_VERSION, id, key, build: identity, status: 'failed', tag: request.tag, reason: got.reason, detail: got.detail};
    if (answer.status === 'printed') stats.drawn += 1;
    else stats.failed += 1;
    if (file && answer.status === 'printed') {
      mkdirSync(resolve(cache), {recursive: true});
      // Written whole, then moved in place: a reader never sees half a file.
      writeFileSync(`${file}.${process.pid}.tmp`, `${JSON.stringify({...answer, id: null})}\n`);
      renameSync(`${file}.${process.pid}.tmp`, file);
    }
    return answer;
  }

  /** Answers to many requests, in their order, `concurrency` drawn at once. */
  async function renderMany(requests) {
    const answers = new Array(requests.length);
    let next = 0;
    const worker = async () => {
      for (let at = next++; at < requests.length; at = next++) answers[at] = await render(requests[at]);
    };
    await Promise.all(Array.from({length: Math.max(1, Math.min(concurrency, requests.length))}, worker));
    return answers;
  }

  async function close() {
    if (browser && !given) await browser.close();
    if (site) await site.close();
  }
  return {render, renderMany, close, build: identity, stats, get origin() { return site?.origin ?? null; }};
}

/** One request, one renderer. */
export async function renderFirstPaint(request, options = {}) {
  const renderer = await createRenderer(options);
  try {
    return await renderer.render(request);
  } finally {
    await renderer.close();
  }
}

// ---------- the command line ----------

export const USAGE = `Usage: node render.mjs --distr=<root> [options] < request.json
       node render.mjs --distr=<root> --session [options]

  --distr=<root>       the Framework build: a pair's distr/ (or a ui-builder output);
                       the pair's own copy defaults to the distr/ it is in
  --session            JSON lines: one request per line on stdin, one answer per line on stdout, in order
  --cache=<dir>        keep answers by key there; a request answered before starts no browser
  --build=<id>         the build's identity in the key (a pair id); default: the sha256 of its files
  --config=<file>      a first-paint configuration (component packages, clock)
  --concurrency=<n>    components drawn at once (default 2)
  --port=<n>           the build server's port (default: any free port)
  --playwright=<dir>   the playwright package folder (default: the one the current folder resolves)
  --strict             exit 1 when a request is refused, unknown or failed`;

const flagOf = (argv, name) => {
  const found = argv.find((one) => one.startsWith(`--${name}=`));
  return found ? found.slice(name.length + 3) : null;
};

/** Runs the command line; `defaults.distr` is the pair's own distr/ for its copy. Answers the exit code. */
export async function main(argv, {defaults = {}, stdin = process.stdin, stdout = process.stdout, stderr = process.stderr} = {}) {
  if (argv.includes('--help') || argv.includes('-h')) {
    stdout.write(`${USAGE}\n`);
    return 0;
  }
  const distr = flagOf(argv, 'distr') ?? defaults.distr ?? null;
  if (!distr || !existsSync(distr) || !statSync(distr).isDirectory()) {
    stderr.write(`${USAGE}\n`);
    return 2;
  }
  const renderer = await createRenderer({
    distr,
    config: flagOf(argv, 'config'),
    build: flagOf(argv, 'build'),
    cache: flagOf(argv, 'cache'),
    concurrency: Number(flagOf(argv, 'concurrency') ?? 2),
    port: Number(flagOf(argv, 'port') ?? 0),
    playwright: flagOf(argv, 'playwright'),
  });
  let bad = 0;
  const count = (answer) => { if (answer.status !== 'printed') bad += 1; return answer; };
  try {
    if (argv.includes('--session')) {
      // Answers leave in the order the requests came, each as soon as it and
      // every one before it is done.
      const lines = createInterface({input: stdin, crlfDelay: Infinity});
      const pending = [];
      let written = 0;
      const flush = () => {
        while (written < pending.length && pending[written].done) {
          stdout.write(`${JSON.stringify(pending[written].answer)}\n`);
          written += 1;
        }
      };
      const slots = [];
      for await (const line of lines) {
        if (!line.trim()) continue;
        const one = {done: false, answer: null};
        pending.push(one);
        let request;
        try { request = JSON.parse(line); } catch { request = Symbol.for('not-json'); }
        const job = (request === Symbol.for('not-json')
          ? Promise.resolve({schema: SCHEMA, schema_version: SCHEMA_VERSION, id: null, build: renderer.build, status: 'refused', tag: null, reason: 'not-json', detail: 'a line is one JSON request'})
          : renderer.render(request)).then((answer) => { one.answer = count(answer); one.done = true; flush(); });
        slots.push(job);
        // At most `concurrency` drawn at once: wait for the oldest beyond it.
        if (slots.length >= Number(flagOf(argv, 'concurrency') ?? 2)) await slots.shift();
      }
      await Promise.all(slots);
      flush();
    } else {
      let text = '';
      for await (const chunk of stdin) text += chunk;
      let input;
      try { input = JSON.parse(text); } catch {
        stderr.write('stdin is not JSON: one request object or an array of them\n');
        return 2;
      }
      const answers = Array.isArray(input) ? await renderer.renderMany(input) : [await renderer.render(input)];
      answers.forEach(count);
      stdout.write(`${JSON.stringify(Array.isArray(input) ? answers : answers[0], null, 2)}\n`);
    }
  } finally {
    await renderer.close();
  }
  const {stats} = renderer;
  stderr.write(`first-paint render: ${stats.requests} requests, ${stats.drawn} drawn, ${stats.cached} from the cache, ${stats.refused} refused, ${stats.unknown} unknown, ${stats.failed} failed\n`);
  return argv.includes('--strict') && bad ? 1 : 0;
}

if (import.meta.url === pathToFileURL(resolve(process.argv[1] ?? '')).href) {
  // Exit when answered: a closed Playwright browser can leave a handle that
  // holds the process open after the last answer.
  process.exit(await main(process.argv.slice(2)));
}
